// Feature-audit deepening (2026-10-08): PDF-01 — import and read PDFs of each
// kind (generated by tick7/fixture/mkpdf.py): 20-page text, 3-page image-only
// "scan", 300-page text, 30 MB image-heavy, truncated, and an HTML file named
// .pdf. Measures first page time, page/text layers, zoom, reading position after
// reopen, and the 390 px phone layout. Desktop import goes through the real
// sidebar "+" → PDF file chooser.
import { test, type Page } from "@playwright/test";
import { ready, BASE, H } from "../fullstack/helpers";
import { readFileSync } from "node:fs";

const FX = "/var/home/oandy/桌面/git/note/Onden/.acceptance/feature-loop-2026-10-07/tick7/fixture";

async function view(p: Page) {
  return p.evaluate(() => {
    const sc = document.querySelector(".pagebook-scroll") as HTMLElement | null;
    const pages = document.querySelectorAll("[data-page-key]");
    const first = pages[0] as HTMLElement | undefined;
    return {
      pages: pages.length,
      rendered: document.querySelectorAll(".pdf-page-canvas canvas").length,
      textSpans: document.querySelectorAll(".pdf-text-layer span").length,
      error: (document.querySelector(".pdf-node-error") as HTMLElement | null)?.innerText ?? null,
      pageW: first ? Math.round(first.getBoundingClientRect().width) : null,
      scrollTop: sc ? Math.round(sc.scrollTop) : null,
      scrollH: sc ? sc.scrollHeight : null,
      pageIndicator: (document.querySelector("[class*='page-number'], [class*='pageNumber'], .pdf-node-page") as HTMLElement | null)?.innerText ?? null,
    };
  });
}
async function waitFirst(p: Page, ms = 60_000) {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) {
    const v = await view(p).catch(() => null);
    if (v && (v.rendered > 0 || v.error)) return Date.now() - t0;
    await p.waitForTimeout(200);
  }
  return -1;
}

test("PDF-01: kinds, zoom, reopen position, phone", async ({ page }) => {
  test.setTimeout(480_000);
  const stamp = Date.now();
  const out: Record<string, unknown> = {};
  const req = page.request;
  const upload = async (file: string) => {
    const r = await req.post("/api/media", { headers: { origin: BASE }, multipart: { file: { name: `${file.replace(".pdf", "")}-${stamp}.pdf`, mimeType: "application/pdf", buffer: readFileSync(`${FX}/${file}`) } }, timeout: 120_000 });
    const j = await r.json().catch(() => ({}));
    return { status: r.status(), url: (j as { url?: string }).url ?? "", err: r.ok() ? "" : JSON.stringify(j).slice(0, 100) };
  };
  const mkPdfNode = async (title: string, url: string) => {
    const n = await (await req.post("/api/nodes", { ...H, data: { title, markdown: "" } })).json();
    await req.put(`/api/nodes/${n.id}/attributes/pdf_url`, { ...H, data: { value: url, value_type: "text" } });
    return n.id as string;
  };

  // Desktop import through the UI.
  await ready(page, "/?view=notes");
  await page.locator(".membership-gate").waitFor({ state: "hidden", timeout: 90_000 }).catch(() => {});
  await page.locator('button[aria-label="Create new node"]').click();
  const pdfItem = page.locator(".sidebar-sort-menu-item", { hasText: /PDF/ });
  out.uiPdfItem = await pdfItem.count();
  if (await pdfItem.count()) {
    const [chooser] = await Promise.all([page.waitForEvent("filechooser"), pdfItem.first().click()]);
    await chooser.setFiles({ name: `text20-ui-${stamp}.pdf`, mimeType: "application/pdf", buffer: readFileSync(`${FX}/text20.pdf`) });
    out.uiFirstPageMs = await waitFirst(page);
    out.uiView = await view(page);
    out.uiUrl = page.url().replace(BASE, "");
  }

  const results: Record<string, unknown> = {};
  const ids: Record<string, string> = {};
  for (const f of ["text20.pdf", "scan3.pdf", "big300.pdf", "bigscan.pdf", "broken.pdf", "notpdf.pdf"]) {
    const up = await upload(f);
    if (!up.url) { results[f] = { upload: up.status, err: up.err }; continue; }
    const id = await mkPdfNode(`PDF01 ${f} ${stamp}`, up.url);
    ids[f] = id;
    const t0 = Date.now();
    await ready(page, `/?view=notes&node=${id}`);
    const firstMs = await waitFirst(page);
    await page.waitForTimeout(1500);
    const heap = await page.evaluate(() => (performance as unknown as { memory?: { usedJSHeapSize: number } }).memory?.usedJSHeapSize ?? 0);
    results[f] = { upload: up.status, openToFirstPageMs: firstMs, totalMs: Date.now() - t0, heapMB: Math.round(heap / 1e6), ...(await view(page)) };
  }
  out.kinds = results;

  // Zoom + scroll + reopen on the 20-page text PDF.
  const tid = ids["text20.pdf"];
  if (tid) {
    await ready(page, `/?view=notes&node=${tid}`);
    await waitFirst(page);
    await page.waitForTimeout(1000);
    const w0 = (await view(page)).pageW;
    await page.locator("[data-pdf-more]").click(); await page.getByRole("menuitem", { name: "Zoom in" }).click();
    await page.waitForTimeout(800);
    const w1 = (await view(page)).pageW;
    await page.locator("[data-pdf-more]").click(); await page.getByRole("menuitem", { name: "Fit width" }).click();
    await page.waitForTimeout(800);
    const w2 = (await view(page)).pageW;
    out.zoom = `start ${w0} → zoomIn ${w1} → fit ${w2}`;
    await page.evaluate(() => { const sc = document.querySelector(".pagebook-scroll") as HTMLElement; sc.scrollTop = sc.scrollHeight * 0.5; });
    await page.waitForTimeout(1200);
    out.scrolledTo = await view(page);
    // Leave and come back (in-app), then reload.
    await ready(page, `/?view=notes`);
    await page.waitForTimeout(800);
    await ready(page, `/?view=notes&node=${tid}`);
    await waitFirst(page);
    await page.waitForTimeout(1200);
    out.reopen = await view(page);
  }

  // Phone.
  await page.setViewportSize({ width: 390, height: 800 });
  if (tid) {
    await ready(page, `/?view=notes&node=${tid}`);
    await waitFirst(page);
    await page.waitForTimeout(1500);
    out.phone = {
      ...(await view(page)),
      pageOverflow: await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 2),
      toolbar: await page.locator(".pdf-node-bar").evaluate((el) => `${el.scrollWidth}/${el.clientWidth} h=${Math.round(el.getBoundingClientRect().height)}`).catch(() => "(none)"),
      contentH: await page.locator(".pdf-node-content").evaluate((el) => Math.round(el.getBoundingClientRect().height)).catch(() => 0),
      smallButtons: await page.locator(".pdf-node-bar button").evaluateAll((bs) => bs.filter((b) => b.getBoundingClientRect().height < 44).map((b) => `${(b as HTMLElement).getAttribute("title") ?? ""}:${Math.round(b.getBoundingClientRect().height)}`)),
    };
    await page.screenshot({ path: `${process.env.SHOT_DIR ?? "/tmp"}/pdf01-phone.png` }).catch(() => {});
  }
  console.log("PDF01 " + JSON.stringify(out, null, 2));
});
